class Solution:
    def minOperations(self, nums: List[int]) -> int:
        LIM = 100004
        sieve = bytearray([1]) * LIM
        sieve[0] = sieve[1] = 0
        for i in range(2, int(LIM ** 0.5) + 1):
            if sieve[i]:
                sieve[i*i::i] = bytearray(len(sieve[i*i::i]))
        nxt = [0] * LIM
        p = LIM
        for v in range(LIM - 1, -1, -1):
            if sieve[v]: p = v
            nxt[v] = p
        ans = 0
        for i, v in enumerate(nums):
            if i % 2 == 0:
                ans += nxt[v] - v
            elif sieve[v]:
                ans += 1 if not sieve[v + 1] else 2
        return ans

