class Solution {
public:
    int minOperations(vector<int>& nums) {
        const int LIM = 100004;
        vector<bool> sv(LIM, true); sv[0] = sv[1] = false;
        for (int i = 2; i * i < LIM; i++)
            if (sv[i]) for (int j = i * i; j < LIM; j += i) sv[j] = false;
        vector<int> nxt(LIM); int p = LIM;
        for (int v = LIM - 1; v >= 0; v--) { if (sv[v]) p = v; nxt[v] = p; }
        long ans = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            int v = nums[i];
            if (i % 2 == 0) ans += nxt[v] - v;
            else if (sv[v]) ans += sv[v + 1] ? 2 : 1;
        }
        return (int)ans;
    }
};

