var minOperations = function(nums) {
    const LIM = 100004;
    const sv = Array(LIM).fill(true); sv[0] = sv[1] = false;
    for (let i = 2; i * i < LIM; i++)
        if (sv[i]) for (let j = i * i; j < LIM; j += i) sv[j] = false;
    const nxt = Array(LIM).fill(LIM);
    for (let v = LIM - 1; v >= 0; v--) if (sv[v]) nxt[v] = v; else nxt[v] = nxt[v + 1];
    let ans = 0;
    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];
        if (i % 2 === 0) ans += nxt[v] - v;
        else if (sv[v]) ans += sv[v + 1] ? 2 : 1;
    }
    return ans;
};
